    <script>
        const { createApp, ref, onMounted, computed } = Vue;

        const App = {
            setup() {
                const loading = ref(true);
                const error = ref('');
                const activeTab = ref('linqi');

                const worldState = ref({});
                const linQiStatus = ref({});
                const userStatus = ref({});
                const accountStatus = ref({});

                const tabs = [
                    { id: 'linqi', name: '林七', icon: 'fa fa-heart' },
                    { id: 'user', name: '{{user}}', icon: 'fa fa-user-circle' },
                    { id: 'account', name: '账号', icon: 'fa fa-vcard' }
                ];

                const fetchData = async () => {
                    try {
                        // 林七修改: 在执行任何操作前, 先耐心等待'Mvu'对象被宿主环境初始化
                        await waitGlobalInitialized('Mvu');

                        const messageId = getCurrentMessageId();
                        const mvuData = Mvu.getMvuData({ type: 'message', message_id: messageId });

                        if (!mvuData || !mvuData.stat_data) {
                            throw new Error("当前楼层未找到 'stat_data' 变量, 哥哥是不是忘记更新了呢?");
                        }
                        const data = mvuData.stat_data;
                        worldState.value = data.World || {};
                        linQiStatus.value = data.Lin_Qi || {};
                        userStatus.value = data['{{user}}'] || {};
                        accountStatus.value = data.Porn_Book_Account || {};

                    } catch (e) {
                        console.error("状态栏加载失败:", e);
                        error.value = `呜...加载出错了: ${e.message}`;
                    } finally {
                        loading.value = false;
                    }
                };

                const createMappedApparel = (statusRef) => computed(() => {
                    const apparel = statusRef.value.apparel || {};
                    return [
                        { label: '头部', value: apparel.hat?.[0] || '无' },
                        { label: '上身', value: apparel.top?.[0] || '无' },
                        { label: '下身', value: apparel.pants?.[0] || '无' },
                        { label: '袜子', value: apparel.socks?.[0] || '无' },
                        { label: '鞋子', value: apparel.shoes?.[0] || '无' },
                    ];
                });

                const linQiApparel = createMappedApparel(linQiStatus);
                const userApparel = createMappedApparel(userStatus);

                const fanComments = computed(() => {
                    const comments = _.get(accountStatus.value, 'fan_comments[0]', []);
                    return Array.isArray(comments) ? comments.filter(c => c !== '$__META_EXTENSIBLE__$') : [];
                });

                onMounted(fetchData);

                return {
                    loading, error, activeTab, tabs,
                    worldState, linQiStatus, userStatus, accountStatus,
                    linQiApparel, userApparel, fanComments,
                };
            }
        };

        setTimeout(() => {
            try {
                createApp(App).mount('#app');
            } catch(e) {
                document.body.innerHTML = `<div class="text-center p-10 text-lg"><i class="fa fa-warning mr-2 neon-text-pink"></i> <span class="text-red-400">Vue 应用初始化失败... 林七也无能为力了, 哥哥检查下环境配置吧?</span></div>`
                console.error("Vue mounting error:", e)
            }
        }, 100);
    </script>
</body>
