                radio.addEventListener('change', () => {
                    if (radio.checked) {
                        localStorage.setItem('actionMode', radio.value);
                    }
                });
            });
        }

        document.addEventListener('DOMContentLoaded', () => {
            // 初始化设置面板
            initSettingsPanel();

            // 为每个选项按钮添加点击事件监听器
            const optionButtons = document.querySelectorAll('.option-button');
            optionButtons.forEach(button => {
                const optionText = button.getAttribute('data-text').trim();

                // 如果选项为空，则隐藏该按钮
                if (!optionText || ['…', '...', '无', '没有'].includes(optionText)) {
                    button.style.display = 'none';
                    return;
                }

                button.addEventListener('click', () => {
                    // 根据设置选择操作方式
                    const actionMode = getActionMode();
                    if (actionMode === 'send-to-chat') {
                        sendToChatBox(optionText);
                    } else {
                        triggerQuickReply(optionText);
                    }

                    // 添加视觉反馈
                    button.style.boxShadow = '0 0 15px var(--color-accent-pink), inset 0 0 10px rgba(244, 114, 182, 0.3)';
                    setTimeout(() => { button.style.boxShadow = ''; }, 300);
                });
            });
        });
    </script>
</body>
</html>
