<body>
    <div class="decoration dec-1">💕</div>
    <div class="decoration dec-2">💕</div>

    <div class="game-container">
        <h1 class="game-title">💕 与妹妹做黄播 💕
            <button class="settings-btn-new" title="设置">
                ⚙️
            </button>
        </h1>

        <div class="settings-panel">
            <div class="settings-content">
                <div class="settings-header">
                    <h2 class="settings-title">设置</h2>
                    <button class="close-btn">&times;</button>
                </div>

                <div class="settings-group">
                    <label class="settings-label">行动选项点击处理</label>
                    <div class="action-mode-options">
                        <label class="action-mode-option">
                            <input type="radio" name="action-mode" value="send-to-chat" id="send-to-chat-mode" checked />
                            <span class="radio-custom"></span>
                            <div class="option-content">
                                <span class="option-title">发送到酒馆聊天框</span>
                                <span class="option-desc">点击后将选项文本添加到聊天输入框中</span>
                            </div>
                        </label>
                        <label class="action-mode-option">
                            <input type="radio" name="action-mode" value="direct-execute" id="direct-execute-mode" />
                            <span class="radio-custom"></span>
                            <div class="option-content">
                                <span class="option-title">点击直接执行</span>
                                <span class="option-desc">点击后立即发送消息并触发回复</span>
                            </div>
                        </label>
                    </div>
                </div>
            </div>
        </div>

        <div id="maintext-container">$1</div>

        <div id="options-container">
            <button class="option-button" data-text="$2">$2</button>
            <button class="option-button" data-text="$3">$3</button>
            <button class="option-button" data-text="$4">$4</button>
            <button class="option-button" data-text="$5">$5</button>
        </div>
    </div>

    <script>
        const triggerQuickReply = text => {
            if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${text}|/trigger`);
            } else {
                console.log('SillyTavern environment not detected. Would send:', text);
            }
        };

        const sendToChatBox = text => {
            if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;

            try {
                const $textarea = $(parent.document).find('#send_textarea');
                if ($textarea.length === 0) { console.log('未找到聊天输入框 (#send_textarea)'); return; }
                const currentContent = $textarea.val() || '';
                if (currentContent.includes(text.trim())) { console.log('聊天框中已包含该文本，跳过添加'); return; }
                const separator = currentContent.trim() ? '\n' : '';
                const newContent = currentContent + separator + text.trim();
                $textarea.val(newContent);
                $textarea.trigger('input');
                console.log('已添加文本到聊天框:', text.trim());
            } catch (error) {
                console.error('发送到聊天框时出错:', error);
                triggerQuickReply(text);
            }
        };

        function getActionMode() {
            return localStorage.getItem('actionMode') || 'send-to-chat';
        }

        function initSettingsPanel() {
            const settingsBtn = document.querySelector('.settings-btn-new');
            const settingsPanel = document.querySelector('.settings-panel');
            const closeBtn = document.querySelector('.close-btn');
            const actionModeRadios = document.querySelectorAll('input[name="action-mode"]');

            settingsBtn.addEventListener('click', () => {
                settingsPanel.style.display = 'flex';
                document.body.style.overflow = 'hidden';
            });

            const closeSettings = () => {
                settingsPanel.style.display = 'none';
                document.body.style.overflow = '';
            };

            closeBtn.addEventListener('click', closeSettings);
            settingsPanel.addEventListener('click', e => { if (e.target === settingsPanel) closeSettings(); });
            document.addEventListener('keydown', e => { if (e.key === 'Escape' && settingsPanel.style.display === 'flex') closeSettings(); });

            const savedActionMode = getActionMode();
            actionModeRadios.forEach(radio => {
                radio.checked = (radio.value === savedActionMode);
                radio.addEventListener('change', () => { if (radio.checked) { localStorage.setItem('actionMode', radio.value); } });
            });
        }

        document.addEventListener('DOMContentLoaded', () => {
            initSettingsPanel();

            const maintextContainer = document.getElementById('maintext-container');
            if (maintextContainer) {
                const rawMarkdown = maintextContainer.textContent.trim();
                maintextContainer.innerHTML = marked.parse(rawMarkdown, { breaks: true, gfm: true });
            }

            document.querySelectorAll('.option-button').forEach(button => {
                const optionText = button.getAttribute('data-text').trim();
                if (!optionText || ['…', '...', '无', '没有'].includes(optionText)) {
                    button.style.display = 'none';
                    return;
                }
                button.addEventListener('click', () => {
                    (getActionMode() === 'send-to-chat') ? sendToChatBox(optionText) : triggerQuickReply(optionText);
                    button.style.backgroundColor = 'rgba(255, 102, 153, 0.3)';
                    setTimeout(() => { button.style.backgroundColor = ''; }, 300);
                });
            });
        });
    </script>
</body>
</html>
