entries.content:
{
  "name": "江城南站",
  "parent_realm": "江城，南部交通枢纽区",
  "summary": "江城最重要的高速铁路客运站，一座充满未来感的现代化大型交通枢纽。其巨大的流线型穹顶和高效的换乘系统是城市发展的象征，连接着江城与全国各大主要城市。",
  "locations": [
    {
      "name": "出发大厅",
      "summary": "采用无柱式穹顶设计的巨大空间，阳光透过顶部的玻璃幕墙洒下。厅内电子显示屏滚动着车次信息，人流如织但井然有序。",
      "layout": "位于车站主体建筑的二层，通过多个入口与站前广场相连。"
    },
    {
      "name": "站台层",
      "summary": "多条轨道并列的地下或半地下空间，一列列白色车身的动车组安静地停靠或缓缓驶离，月台上有序地引导着旅客上下车。",
      "layout": "位于出发大厅的正下方，通过检票口和扶梯连接。"
    },
    {
      "name": "站前广场",
      "summary": "一个宽阔的开放式广场，集成了公交车站、出租车候客区和地铁入口。广场中央矗立着一座名为“启航”的抽象金属雕塑。",
      "layout": "位于车站主建筑的正前方，是进入车站的第一个区域。"
    }
  ]
}

